// Stage the Pages project root (config PATHS.stage): wrangler.toml generated from config + functions/ + lib/.
// out/ is already there (assemble.mjs). pages_build_output_dir is relative to this wrangler.toml.
import fs from "node:fs";
import path from "node:path";
import { PAGES, PATHS } from "../config.mjs";
import { copy, writeText } from "../lib/fsx.mjs";

export function pagesWranglerToml() {
  const s = PAGES.serviceBinding;
  return [
    "# Generated by deploy/cloudflare/deploy/pages_project.mjs from config.mjs. Do not edit here.",
    `name = "${PAGES.project}"`,
    `pages_build_output_dir = "${path.relative(PATHS.stage, PATHS.out).split(path.sep).join("/")}"`,
    `compatibility_date = "${PAGES.compatibilityDate}"`,
    "",
    "[[services]]",
    `binding = "${s.binding}"`,
    `service = "${s.service}"`,
    "",
  ].join("\n");
}

export function stagePagesProject() {
  for (const sub of ["functions", "lib"]) {
    const dest = path.join(PATHS.stage, sub);
    fs.rmSync(dest, { recursive: true, force: true });
    copy(path.join(PATHS.pagesSrc, sub), dest);
  }
  writeText(path.join(PATHS.stage, "wrangler.toml"), pagesWranglerToml());
  if (!fs.existsSync(path.join(PATHS.out, "_routes.json"))) throw new Error("out/ is not assembled: run assemble.mjs first");
  return PATHS.stage;
}
